import type { ErrorRequestHandler, RequestHandler } from 'express';
import { ZodError } from 'zod';
import { HttpError } from '../lib/http-error.js';

export const notFoundHandler: RequestHandler = (req, res) => {
  res.status(404).json({ error: { message: `Route not found: ${req.method} ${req.path}` } });
};

export const errorHandler: ErrorRequestHandler = (err: unknown, _req, res, _next) => {
  if (err instanceof ZodError) {
    res.status(400).json({ error: { message: 'Invalid request', issues: err.issues } });
    return;
  }
  if (err instanceof HttpError) {
    res.status(err.status).json({ error: { message: err.message } });
    return;
  }
  console.error(err);
  res.status(500).json({ error: { message: 'Internal server error' } });
};

import { z } from 'zod';

/**
 * Our standardized filing — one row per filing, as opposed to EDGAR's columnar format.
 * This is the only domain type exposed by the API.
 */
export const FilingSchema = z.object({
  accessionNumber: z.string(),
  cik: z.string(),
  form: z.string(),
  filingDate: z.iso.date(),
  reportDate: z.iso.date().nullable(),
  acceptedAt: z.string(),
  primaryDocument: z.string(),
  description: z.string().nullable(),
  sizeBytes: z.number().int(),
  /** Link to the primary document on sec.gov */
  url: z.url(),
  /** Link to the filing index page (all documents in the filing) */
  indexUrl: z.url(),
});

export type Filing = z.infer<typeof FilingSchema>;

export const TickerSchema = z
  .string()
  .trim()
  .min(1)
  .max(12)
  .regex(/^[A-Za-z0-9.-]+$/, 'Invalid ticker')
  .transform((t) => t.toUpperCase());

