import { z } from 'zod';

/**
 * Raw EDGAR response shapes. We validate only the fields we use; EDGAR adds fields over time
 * and zod strips unknown keys by default.
 */

/** https://www.sec.gov/files/company_tickers.json — `{ "0": {...}, "1": {...} }` */
export const EdgarCompanyTickersSchema = z.record(
  z.string(),
  z.object({
    cik_str: z.number().int(),
    ticker: z.string(),
    title: z.string(),
  }),
);

/** Columnar block: each key is an array, index i across all arrays = filing i. */
export const EdgarFilingColumnsSchema = z.object({
  accessionNumber: z.array(z.string()),
  filingDate: z.array(z.string()),
  reportDate: z.array(z.string()),
  acceptanceDateTime: z.array(z.string()),
  form: z.array(z.string()),
  primaryDocument: z.array(z.string()),
  primaryDocDescription: z.array(z.string()),
  size: z.array(z.number()),
});

/** https://data.sec.gov/submissions/CIK##########.json */
export const EdgarSubmissionsSchema = z.object({
  cik: z.string(),
  name: z.string(),
  tickers: z.array(z.string()),
  filings: z.object({
    /** Most recent ≥1000 filings (or ≥1 year, whichever is more). */
    recent: EdgarFilingColumnsSchema,
    /** Older filings, paged into extra files: data.sec.gov/submissions/{name} */
    files: z.array(
      z.object({
        name: z.string(),
        filingCount: z.number(),
        filingFrom: z.string(),
        filingTo: z.string(),
      }),
    ),
  }),
});

export type EdgarFilingColumns = z.infer<typeof EdgarFilingColumnsSchema>;
export type EdgarSubmissions = z.infer<typeof EdgarSubmissionsSchema>;

