import type { z } from 'zod';
import { UpstreamError } from '../../lib/http-error.js';
import {
  EdgarCompanyTickersSchema,
  EdgarSubmissionsSchema,
  type EdgarSubmissions,
} from './edgar.schemas.js';

const TICKERS_URL = 'https://www.sec.gov/files/company_tickers.json';
const SUBMISSIONS_BASE_URL = 'https://data.sec.gov/submissions';
const TICKER_MAP_TTL_MS = 24 * 60 * 60 * 1000;

export interface FilingsRepository {
  /** Returns the zero-padded 10-digit CIK, or undefined if the ticker is unknown. */
  findCikByTicker(ticker: string): Promise<string | undefined>;
  getSubmissions(cik: string): Promise<EdgarSubmissions>;
}

/** Data access for EDGAR. Knows about HTTP + raw EDGAR shapes; nothing about our domain. */
export class EdgarFilingsRepository implements FilingsRepository {
  private tickerMap: { value: Promise<Map<string, string>>; expiresAt: number } | undefined;

  constructor(private readonly userAgent: string) {}

  async findCikByTicker(ticker: string): Promise<string | undefined> {
    const map = await this.getTickerMap();
    return map.get(ticker.toUpperCase());
  }

  getSubmissions(cik: string): Promise<EdgarSubmissions> {
    return this.fetchJson(`${SUBMISSIONS_BASE_URL}/CIK${cik}.json`, EdgarSubmissionsSchema);
  }

  private getTickerMap(): Promise<Map<string, string>> {
    if (!this.tickerMap || this.tickerMap.expiresAt < Date.now()) {
      const value = this.fetchJson(TICKERS_URL, EdgarCompanyTickersSchema).then(
        (raw) =>
          new Map(
            Object.values(raw).map((c) => [
              c.ticker.toUpperCase(),
              String(c.cik_str).padStart(10, '0'),
            ]),
          ),
      );
      // Don't cache failures.
      value.catch(() => {
        this.tickerMap = undefined;
      });
      this.tickerMap = { value, expiresAt: Date.now() + TICKER_MAP_TTL_MS };
    }
    return this.tickerMap.value;
  }

  private async fetchJson<T extends z.ZodType>(url: string, schema: T): Promise<z.infer<T>> {
    let res: Response;
    try {
      res = await fetch(url, { headers: { 'User-Agent': this.userAgent } });
    } catch (err) {
      throw new UpstreamError(`EDGAR request failed: ${(err as Error).message}`);
    }
    if (!res.ok) {
      throw new UpstreamError(`EDGAR responded ${res.status} for ${url}`);
    }
    const parsed = schema.safeParse(await res.json());
    if (!parsed.success) {
      throw new UpstreamError(`Unexpected EDGAR response shape from ${url}`);
    }
    return parsed.data;
  }
}

