import cors from 'cors';
import express, { type Express } from 'express';
import { FilingsController } from './domains/filings/filings.controller.js';
import type { FilingsRepository } from './domains/filings/filings.repository.js';
import { filingsRouter } from './domains/filings/filings.routes.js';
import { FilingsService } from './domains/filings/filings.service.js';
import { errorHandler, notFoundHandler } from './middleware/error-handler.js';

interface AppDeps {
  filingsRepository: FilingsRepository;
  corsOrigin: string;
}

/** Composition root: wires repository → service → controller. Tests can inject a fake repository. */
export function createApp({ filingsRepository, corsOrigin }: AppDeps): Express {
  const app = express();
  app.use(cors({ origin: corsOrigin }));
  app.use(express.json());

  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });

  const filingsController = new FilingsController(new FilingsService(filingsRepository));
  app.use(filingsRouter(filingsController));

  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

