import { describe, expect, it } from 'vitest';
import { columnsToFilings } from './filings.service.js';

describe('columnsToFilings', () => {
  it('pivots EDGAR columnar data into filing objects with sec.gov links', () => {
    const [filing] = columnsToFilings('0000320193', {
      accessionNumber: ['0000320193-25-000079'],
      filingDate: ['2025-10-31'],
      reportDate: ['2025-09-27'],
      acceptanceDateTime: ['2025-10-31T06:01:26.000Z'],
      form: ['10-K'],
      primaryDocument: ['aapl-20250927.htm'],
      primaryDocDescription: ['10-K'],
      size: [9_000_000],
    });

    expect(filing).toMatchObject({
      form: '10-K',
      filingDate: '2025-10-31',
      url: 'https://www.sec.gov/Archives/edgar/data/320193/000032019325000079/aapl-20250927.htm',
      indexUrl:
        'https://www.sec.gov/Archives/edgar/data/320193/000032019325000079/0000320193-25-000079-index.htm',
    });
  });

  it('maps empty strings to null', () => {
    const [filing] = columnsToFilings('0000320193', {
      accessionNumber: ['0001354457-26-001062'],
      filingDate: ['2026-11-09'],
      reportDate: [''],
      acceptanceDateTime: ['2026-11-09T22:00:55.000Z'],
      form: ['25-NSE'],
      primaryDocument: ['xslF25X02/primary_doc.xml'],
      primaryDocDescription: [''],
      size: [3110],
    });

    expect(filing?.reportDate).toBeNull();
    expect(filing?.description).toBeNull();
  });
