const API_BASE_URL = '/api';

export class ApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

interface ApiErrorBody {
  error?: { message?: string };
}

/** Thin fetch wrapper: prefixes the API base URL, parses JSON, and throws ApiError on non-2xx. */
export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${path}`, init);
  if (!res.ok) {
    const body = (await res.json().catch(() => ({}))) as ApiErrorBody;
    throw new ApiError(res.status, body.error?.message ?? `Request failed (${res.status})`);
  }
  return (await res.json()) as T;
}

/** Mirrors the backend's `Filing` domain type (backend/src/domains/filings/filing.domain.ts). */
export interface Filing {
  accessionNumber: string;
  cik: string;
  form: string;
  filingDate: string;
  reportDate: string | null;
  acceptedAt: string;
  primaryDocument: string;
  description: string | null;
  sizeBytes: number;
  url: string;
  indexUrl: string;
}

export interface ListResponse<T> {
  data: T[];
}

import { apiFetch } from '../../lib/api-client';
import type { Filing, ListResponse } from './filings.domain';

export async function fetchFilings(ticker: string): Promise<Filing[]> {
  const res = await apiFetch<ListResponse<Filing>>(
    `/companies/${encodeURIComponent(ticker)}/filings`,
  );
  return res.data;
}

import { queryOptions, useQuery } from '@tanstack/react-query';
import { fetchFilings } from './filings.service';

export const filingsKeys = {
  all: ['filings'] as const,
  byTicker: (ticker: string) => [...filingsKeys.all, ticker.toUpperCase()] as const,
};

/** Exported so route loaders can prefetch with `queryClient.ensureQueryData(...)`. */
export const filingsQueryOptions = (ticker: string) =>
  queryOptions({
    queryKey: filingsKeys.byTicker(ticker),
    queryFn: () => fetchFilings(ticker),
    staleTime: 5 * 60 * 1000,
  });

export function useFilings(ticker: string) {
  return useQuery(filingsQueryOptions(ticker));
}

import { CssBaseline, StyledEngineProvider, ThemeProvider, createTheme } from '@mui/material';
