import { orderBy } from 'es-toolkit';
import { NotFoundError } from '../../lib/http-error.js';
import type { EdgarFilingColumns } from './edgar.schemas.js';
import type { Filing } from './filing.domain.js';
import type { FilingsRepository } from './filings.repository.js';

/** Business logic: turns raw EDGAR data into our domain model. */
export class FilingsService {
  constructor(private readonly repository: FilingsRepository) {}

  async listFilingsByTicker(ticker: string): Promise<Filing[]> {
    const cik = await this.repository.findCikByTicker(ticker);
    if (!cik) throw new NotFoundError(`Unknown ticker: ${ticker}`);

    const submissions = await this.repository.getSubmissions(cik);
    // TODO: pagination, form-type filter, and older filings from `submissions.filings.files`.
    return orderBy(columnsToFilings(cik, submissions.filings.recent), ['filingDate'], ['desc']);
  }
}

/** EDGAR returns `{ form: [...], filingDate: [...] }`; pivot into one object per filing. */
export function columnsToFilings(cik: string, cols: EdgarFilingColumns): Filing[] {
  const cikNumber = String(Number(cik)); // archive URLs use the unpadded CIK
  return cols.accessionNumber.map((accessionNumber, i) => {
    const accessionPath = accessionNumber.replaceAll('-', '');
    const baseUrl = `https://www.sec.gov/Archives/edgar/data/${cikNumber}/${accessionPath}`;
    const primaryDocument = cols.primaryDocument[i] ?? '';
    return {
      accessionNumber,
      cik,
      form: cols.form[i] ?? '',
      filingDate: cols.filingDate[i] ?? '',
      reportDate: cols.reportDate[i] || null,
      acceptedAt: cols.acceptanceDateTime[i] ?? '',
      primaryDocument,
      description: cols.primaryDocDescription[i] || null,
      sizeBytes: cols.size[i] ?? 0,
      url: primaryDocument ? `${baseUrl}/${primaryDocument}` : `${baseUrl}/`,
      indexUrl: `${baseUrl}/${accessionNumber}-index.htm`,
    };
  });
}

