interface TtlCacheOptions {
  ttlMs: number;
  /** Oldest entries are evicted beyond this size. */
  maxEntries?: number;
  now?: () => number;
}

/**
 * Memoizes an async function per key for `ttlMs`.
 * - Concurrent calls for the same key share one in-flight promise.
 * - Rejected promises are evicted so failures aren't cached.
 */
export function withTtlCache<K, V>(
  fn: (key: K) => Promise<V>,
  { ttlMs, maxEntries = 500, now = Date.now }: TtlCacheOptions,
): (key: K) => Promise<V> {
  const entries = new Map<K, { value: Promise<V>; expiresAt: number }>();

  return (key) => {
    const hit = entries.get(key);
    if (hit && hit.expiresAt > now()) return hit.value;

    const value = fn(key);
    entries.delete(key); // re-insert so Map order = insertion recency
    entries.set(key, { value, expiresAt: now() + ttlMs });
    value.catch(() => {
      if (entries.get(key)?.value === value) entries.delete(key);
    });

    if (entries.size > maxEntries) {
      const oldest = entries.keys().next();
      if (!oldest.done) entries.delete(oldest.value);
    }
    return value;
  };
}

