import { delay } from 'es-toolkit';

/**
 * Spaces out calls so at most `maxPerSecond` start per second.
 * EDGAR's fair-access policy is 10 req/s; exceeding it gets the IP temporarily blocked.
 */
export function createRateLimiter(
  maxPerSecond: number,
  now: () => number = Date.now,
): <T>(task: () => Promise<T>) => Promise<T> {
  const intervalMs = 1000 / maxPerSecond;
  let nextSlot = 0;

  return async (task) => {
    const start = Math.max(now(), nextSlot);
    nextSlot = start + intervalMs;
    const wait = start - now();
    if (wait > 0) await delay(wait);
    return task();
  };
}

