import { z } from 'zod';

/** Our standardized filing: one object per filing, unlike EDGAR's columnar arrays. */
export interface Filing {
  accessionNumber: string;
  form: string;
  /** YYYY-MM-DD */
  filingDate: string;
  /** Period the filing covers (YYYY-MM-DD), if any. */
  reportDate: string | null;
  /** ISO timestamp when EDGAR accepted the filing. */
  acceptedAt: string;
  description: string | null;
  primaryDocument: string;
  sizeBytes: number;
  /** Primary document on sec.gov */
  url: string;
  /** Filing index page on sec.gov (lists every document in the filing) */
  indexUrl: string;
}

export interface Company {
  /** Zero-padded 10-digit CIK, as used by data.sec.gov */
  cik: string;
  name: string;
  tickers: string[];
}

export interface CompanyFilings {
  company: Company;
  filings: Filing[];
}

export type SortOrder = 'asc' | 'desc';

export interface FilingsQuery {
  page: number;
  pageSize: number;
  /** Uppercased form types to keep; empty = all. */
  forms: string[];
  order: SortOrder;
}

export interface Pagination {
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
}

export interface FilingsPage {
  company: Company;
  data: Filing[];
  pagination: Pagination;
  /** Distinct form types for this company (unfiltered), for building filter controls. */
  availableForms: string[];
}

export interface CompanySummary {
  ticker: string;
  company: Company;
  /** Filing counts per form type within the window. */
  formCounts: Record<string, number>;
  totalFilings: number;
  /** filingDate of the most recent 10-K, or null (e.g. foreign issuers file 20-F instead). */
  latest10KDate: string | null;
}

export interface SummaryError {
  ticker: string;
  status: number;
  message: string;
}

export interface FilingsSummary {
  /** Inclusive window start/end (YYYY-MM-DD). */
  window: { from: string; to: string };
  data: CompanySummary[];
  /** Tickers that couldn't be summarized (unknown ticker, EDGAR down, …). */
  errors: SummaryError[];
}

/**
 * Tickers are case-insensitive; EDGAR writes share classes with a dash (BRK-B), while users
 * often type a dot (BRK.B).
 */
export const TickerSchema = z
  .string()
  .trim()
  .min(1)
  .max(12)
  .regex(/^[A-Za-z0-9.-]+$/, 'Invalid ticker')
