import type { z } from 'zod';
import { badGateway } from '../../utils/http-error.js';
import { createRateLimiter } from '../../utils/rate-limiter.js';
import { withTtlCache } from '../../utils/ttl-cache.js';
import { toCompanyFilings, toTickerIndex } from './edgar.mapper.js';
import { EdgarCompanyTickersSchema, EdgarSubmissionsSchema } from './edgar.schemas.js';
import type { CompanyFilings } from './filing.domain.js';

const TICKERS_URL = 'https://www.sec.gov/files/company_tickers.json';
const SUBMISSIONS_BASE_URL = 'https://data.sec.gov/submissions';

const HOUR_MS = 60 * 60 * 1000;

/** Data access contract. The service depends on this, not on EDGAR. */
export interface FilingsRepository {
  /** Zero-padded CIK, or undefined if the ticker is unknown. */
  findCikByTicker: (ticker: string) => Promise<string | undefined>;
  getCompanyFilings: (cik: string) => Promise<CompanyFilings>;
}

interface EdgarRepositoryDeps {
  /** SEC requires a descriptive User-Agent with contact info. */
  userAgent: string;
  fetch?: typeof globalThis.fetch;
  /** EDGAR fair-access limit is 10 req/s. */
  maxRequestsPerSecond?: number;
  tickerIndexTtlMs?: number;
  submissionsTtlMs?: number;
}

/** EDGAR-backed repository: HTTP, rate limiting, caching, validation and mapping to domain types. */
export function createEdgarRepository({
  userAgent,
  fetch = globalThis.fetch,
  maxRequestsPerSecond = 10,
  tickerIndexTtlMs = 24 * HOUR_MS,
  submissionsTtlMs = HOUR_MS,
}: EdgarRepositoryDeps): FilingsRepository {
  const rateLimited = createRateLimiter(maxRequestsPerSecond);

  const fetchJson = async <T extends z.ZodType>(url: string, schema: T): Promise<z.infer<T>> => {
    const res = await rateLimited(() => fetch(url, { headers: { 'User-Agent': userAgent } })).catch(
      (err: unknown) => {
        throw badGateway(`EDGAR request failed: ${err instanceof Error ? err.message : 'unknown'}`);
      },
    );
    if (!res.ok) throw badGateway(`EDGAR responded ${res.status} for ${url}`);

    const parsed = schema.safeParse(await res.json());
    if (!parsed.success) throw badGateway(`Unexpected EDGAR response shape from ${url}`);
    return parsed.data;
  };

  // One cache key ('all') for the whole ~800 KB ticker file.
  const getTickerIndex = withTtlCache(
    async (_key: 'all') => toTickerIndex(await fetchJson(TICKERS_URL, EdgarCompanyTickersSchema)),
    { ttlMs: tickerIndexTtlMs },
  );

  const getCompanyFilings = withTtlCache(
    async (cik: string) =>
      toCompanyFilings(
        await fetchJson(`${SUBMISSIONS_BASE_URL}/CIK${cik}.json`, EdgarSubmissionsSchema),
      ),
    { ttlMs: submissionsTtlMs, maxEntries: 200 },
  );

  return {
    findCikByTicker: async (ticker) => (await getTickerIndex('all')).get(ticker.toUpperCase()),
    getCompanyFilings,
  };
}

