import { countBy, orderBy, uniq } from 'es-toolkit';
import { isHttpError, notFound } from '../../utils/http-error.js';
import type {
  CompanyFilings,
  CompanySummary,
  Filing,
  FilingsPage,
  FilingsQuery,
  FilingsSummary,
  Pagination,
  SortOrder,
  SummaryError,
} from './filing.domain.js';
import type { FilingsRepository } from './filings.repository.js';

// ---------- Pure helpers (exported for unit tests) ----------

export const filterByForms = (filings: Filing[], forms: string[]): Filing[] => {
  if (forms.length === 0) return filings;
  const wanted = new Set(forms.map((f) => f.toUpperCase()));
  return filings.filter((f) => wanted.has(f.form.toUpperCase()));
};

/** By filing date; acceptance time breaks ties between same-day filings. */
export const sortByFilingDate = (filings: Filing[], order: SortOrder): Filing[] =>
  orderBy(filings, ['filingDate', 'acceptedAt'], [order, order]);

export const paginate = <T>(
  items: T[],
  page: number,
  pageSize: number,
): { data: T[]; pagination: Pagination } => {
  const start = (page - 1) * pageSize;
  return {
    data: items.slice(start, start + pageSize),
    pagination: {
      page,
      pageSize,
      totalItems: items.length,
      totalPages: Math.ceil(items.length / pageSize),
    },
  };
};

/** Same calendar day one year earlier (UTC), as YYYY-MM-DD. */
export const twelveMonthsBefore = (date: Date): string => {
  const d = new Date(date);
  d.setUTCFullYear(d.getUTCFullYear() - 1);
  return toIsoDate(d);
};

const toIsoDate = (d: Date): string => d.toISOString().slice(0, 10);

export const summarizeFilings = (
  ticker: string,
  { company, filings }: CompanyFilings,
  window: { from: string; to: string },
): CompanySummary => {
  const inWindow = filings.filter((f) => f.filingDate >= window.from && f.filingDate <= window.to);
  // Exact '10-K' only: amendments (10-K/A) aren't a new annual report.
  const latest10K = orderBy(
    filings.filter((f) => f.form === '10-K'),
    ['filingDate'],
    ['desc'],
  )[0];
  return {
    ticker,
    company,
    formCounts: countBy(inWindow, (f) => f.form),
    totalFilings: inWindow.length,
    latest10KDate: latest10K?.filingDate ?? null,
  };
};

// ---------- Service ----------

export interface FilingsService {
  listFilings: (ticker: string, query: FilingsQuery) => Promise<FilingsPage>;
  getSummary: (tickers: string[]) => Promise<FilingsSummary>;
}

interface FilingsServiceDeps {
  repository: FilingsRepository;
  now?: () => Date;
}

export function createFilingsService({
  repository,
  now = () => new Date(),
}: FilingsServiceDeps): FilingsService {
  const getByTicker = async (ticker: string): Promise<CompanyFilings> => {
    const cik = await repository.findCikByTicker(ticker);
    if (!cik) throw notFound(`Unknown ticker: ${ticker}`);
    return repository.getCompanyFilings(cik);
  };

  const listFilings: FilingsService['listFilings'] = async (ticker, query) => {
    const { company, filings } = await getByTicker(ticker);
    const filtered = filterByForms(filings, query.forms);
    const sorted = sortByFilingDate(filtered, query.order);
    return {
      company,
      ...paginate(sorted, query.page, query.pageSize),
      availableForms: uniq(filings.map((f) => f.form)).sort(),
    };
  };

  const getSummary: FilingsService['getSummary'] = async (tickers) => {
    const today = now();
    const window = { from: twelveMonthsBefore(today), to: toIsoDate(today) };

    // One bad ticker shouldn't fail the whole summary: collect per-ticker errors instead.
    const results = await Promise.allSettled(
      tickers.map(async (ticker) => summarizeFilings(ticker, await getByTicker(ticker), window)),
    );

    const data: CompanySummary[] = [];
    const errors: SummaryError[] = [];
    results.forEach((result, i) => {
      const ticker = tickers[i] ?? '';
      if (result.status === 'fulfilled') {
        data.push(result.value);
      } else if (isHttpError(result.reason) && result.reason.expose) {
        errors.push({ ticker, status: result.reason.status, message: result.reason.message });
      } else {
        console.error(result.reason);
        errors.push({ ticker, status: 500, message: 'Internal server error' });
      }
    });

    return { window, data, errors };
  };

  return { listFilings, getSummary };
}

