import { z } from 'zod';

/**
 * Raw EDGAR response shapes. Only fields we use are declared; zod strips the rest,
 * so new EDGAR fields don't break us.
 */

/** https://www.sec.gov/files/company_tickers.json: `{ "0": {...}, "1": {...} }` */
export const EdgarCompanyTickersSchema = z.record(
  z.string(),
  z.object({
    cik_str: z.number().int(),
    ticker: z.string(),
    title: z.string(),
  }),
);

/** Columnar block: index i across every array describes filing i. Missing values are "". */
export const EdgarFilingColumnsSchema = z.object({
  accessionNumber: z.array(z.string()),
  filingDate: z.array(z.string()),
  reportDate: z.array(z.string()),
  acceptanceDateTime: z.array(z.string()),
  form: z.array(z.string()),
  primaryDocument: z.array(z.string()),
  primaryDocDescription: z.array(z.string()),
  size: z.array(z.number()),
});

/** https://data.sec.gov/submissions/CIK##########.json */
export const EdgarSubmissionsSchema = z.object({
  cik: z.string(),
  name: z.string(),
  tickers: z.array(z.string()),
  filings: z.object({
    /** At least the last year or the last 1,000 filings, whichever is more. */
    recent: EdgarFilingColumnsSchema,
    /** Older filings, in extra files at data.sec.gov/submissions/{name}. Not fetched yet. */
    files: z.array(z.object({ name: z.string(), filingCount: z.number() })),
  }),
});

export type EdgarCompanyTickers = z.infer<typeof EdgarCompanyTickersSchema>;
export type EdgarFilingColumns = z.infer<typeof EdgarFilingColumnsSchema>;
export type EdgarSubmissions = z.infer<typeof EdgarSubmissionsSchema>;

import type { CompanyFilings, Filing } from './filing.domain.js';
import type { EdgarCompanyTickers, EdgarFilingColumns, EdgarSubmissions } from './edgar.schemas.js';

const ARCHIVES_BASE_URL = 'https://www.sec.gov/Archives/edgar/data';

export const padCik = (cik: number | string): string => String(cik).padStart(10, '0');

/** Ticker (uppercase) → zero-padded CIK. Several tickers can share a CIK (JPM, JPM-PC, …). */
export const toTickerIndex = (raw: EdgarCompanyTickers): Map<string, string> =>
  new Map(Object.values(raw).map((c) => [c.ticker.toUpperCase(), padCik(c.cik_str)]));

/** EDGAR uses "" for missing values in its columnar arrays. */
const emptyToNull = (value: string | undefined): string | null =>
  value === undefined || value === '' ? null : value;

/** Pivots EDGAR's `{ form: [...], filingDate: [...] }` into one object per filing. */
export function columnsToFilings(cik: string, cols: EdgarFilingColumns): Filing[] {
  const archiveCik = String(Number(cik)); // archive URLs use the unpadded CIK
  return cols.accessionNumber.map((accessionNumber, i): Filing => {
    const folderUrl = `${ARCHIVES_BASE_URL}/${archiveCik}/${accessionNumber.replaceAll('-', '')}`;
    const primaryDocument = cols.primaryDocument[i] ?? '';
    return {
      accessionNumber,
      form: cols.form[i] ?? '',
      filingDate: cols.filingDate[i] ?? '',
      reportDate: emptyToNull(cols.reportDate[i]),
      acceptedAt: cols.acceptanceDateTime[i] ?? '',
      description: emptyToNull(cols.primaryDocDescription[i]),
      primaryDocument,
      sizeBytes: cols.size[i] ?? 0,
      url: primaryDocument ? `${folderUrl}/${primaryDocument}` : `${folderUrl}/`,
      indexUrl: `${folderUrl}/${accessionNumber}-index.htm`,
    };
  });
}

export const toCompanyFilings = (raw: EdgarSubmissions): CompanyFilings => {
  const cik = padCik(raw.cik);
  return {
    company: { cik, name: raw.name, tickers: raw.tickers },
    filings: columnsToFilings(cik, raw.filings.recent),
  };
};

import type { z } from 'zod';
import { badGateway } from '../../utils/http-error.js';
import { createRateLimiter } from '../../utils/rate-limiter.js';
import { withTtlCache } from '../../utils/ttl-cache.js';
import { toCompanyFilings, toTickerIndex } from './edgar.mapper.js';
import { EdgarCompanyTickersSchema, EdgarSubmissionsSchema } from './edgar.schemas.js';
import type { CompanyFilings } from './filing.domain.js';

const TICKERS_URL = 'https://www.sec.gov/files/company_tickers.json';
const SUBMISSIONS_BASE_URL = 'https://data.sec.gov/submissions';

const HOUR_MS = 60 * 60 * 1000;

/** Data access contract. The service depends on this, not on EDGAR. */
export interface FilingsRepository {
  /** Zero-padded CIK, or undefined if the ticker is unknown. */
  findCikByTicker: (ticker: string) => Promise<string | undefined>;
  getCompanyFilings: (cik: string) => Promise<CompanyFilings>;
}

interface EdgarRepositoryDeps {
  /** SEC requires a descriptive User-Agent with contact info. */
  userAgent: string;
  fetch?: typeof globalThis.fetch;
  /** EDGAR fair-access limit is 10 req/s. */
  maxRequestsPerSecond?: number;
  tickerIndexTtlMs?: number;
  submissionsTtlMs?: number;
}

/** EDGAR-backed repository: HTTP, rate limiting, caching, validation and mapping to domain types. */
export function createEdgarRepository({
  userAgent,
  fetch = globalThis.fetch,
  maxRequestsPerSecond = 10,
  tickerIndexTtlMs = 24 * HOUR_MS,
  submissionsTtlMs = HOUR_MS,
}: EdgarRepositoryDeps): FilingsRepository {
  const rateLimited = createRateLimiter(maxRequestsPerSecond);

  const fetchJson = async <T extends z.ZodType>(url: string, schema: T): Promise<z.infer<T>> => {
    const res = await rateLimited(() => fetch(url, { headers: { 'User-Agent': userAgent } })).catch(
      (err: unknown) => {
        throw badGateway(`EDGAR request failed: ${err instanceof Error ? err.message : 'unknown'}`);
      },
    );
    if (!res.ok) throw badGateway(`EDGAR responded ${res.status} for ${url}`);

    const parsed = schema.safeParse(await res.json());
    if (!parsed.success) throw badGateway(`Unexpected EDGAR response shape from ${url}`);
    return parsed.data;
  };

  // One cache key ('all') for the whole ~800 KB ticker file.
  const getTickerIndex = withTtlCache(
    async (_key: 'all') => toTickerIndex(await fetchJson(TICKERS_URL, EdgarCompanyTickersSchema)),
    { ttlMs: tickerIndexTtlMs },
  );

  const getCompanyFilings = withTtlCache(
    async (cik: string) =>
      toCompanyFilings(
        await fetchJson(`${SUBMISSIONS_BASE_URL}/CIK${cik}.json`, EdgarSubmissionsSchema),
      ),
    { ttlMs: submissionsTtlMs, maxEntries: 200 },
  );

  return {
    findCikByTicker: async (ticker) => (await getTickerIndex('all')).get(ticker.toUpperCase()),
    getCompanyFilings,
  };
}

