import type { RequestHandler } from 'express';
import { uniq } from 'es-toolkit';
import { z } from 'zod';
import { TickerSchema } from './filing.domain.js';
import type { FilingsService } from './filings.service.js';

/** Accepts `?x=a,b` and `?x=a&x=b` (and mixes); returns trimmed, non-empty values. */
const csvList = z
  .union([z.string(), z.array(z.string())])
  .optional()
  .transform((v) =>
    (Array.isArray(v) ? v : v === undefined ? [] : [v])
      .flatMap((s) => s.split(','))
      .map((s) => s.trim())
      .filter((s) => s.length > 0),
  );

const ListFilingsParamsSchema = z.object({ ticker: TickerSchema });

const ListFilingsQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(100).default(25),
  /** e.g. `form=10-K,10-Q` */
  form: csvList.transform((forms) => uniq(forms.map((f) => f.toUpperCase()))),
  order: z.enum(['asc', 'desc']).default('desc'),
});

const MAX_SUMMARY_TICKERS = 20;

const SummaryQuerySchema = z.object({
  /** e.g. `tickers=AAPL,SPOT,JPM` */
  tickers: csvList
    .pipe(z.array(TickerSchema))
    .transform((tickers) => uniq(tickers))
    .pipe(
      z
        .array(z.string())
        .min(1, 'Provide at least one ticker, e.g. ?tickers=AAPL,SPOT')
        .max(MAX_SUMMARY_TICKERS, `At most ${MAX_SUMMARY_TICKERS} tickers`),
    ),
});

export interface FilingsController {
  listFilings: RequestHandler;
  getSummary: RequestHandler;
}

/** HTTP layer: validate input, call the service, send the response. No business logic. */
export const createFilingsController = (service: FilingsService): FilingsController => ({
  listFilings: async (req, res) => {
    const { ticker } = ListFilingsParamsSchema.parse(req.params);
    const { form, ...rest } = ListFilingsQuerySchema.parse(req.query);
    res.json(await service.listFilings(ticker, { ...rest, forms: form }));
  },

  getSummary: async (req, res) => {
    const { tickers } = SummaryQuerySchema.parse(req.query);
    res.json(await service.getSummary(tickers));
  },
});

