import type { Company, CompanyFilings, Filing } from './filing.domain.js';
import type { FilingsRepository } from './filings.repository.js';

export const makeFiling = (overrides: Partial<Filing> = {}): Filing => ({
  accessionNumber: `0000000000-00-${String(Math.random()).slice(2, 8)}`,
  form: '8-K',
  filingDate: '2026-01-01',
  reportDate: null,
  acceptedAt: '2026-01-01T12:00:00.000Z',
  description: null,
  primaryDocument: 'doc.htm',
  sizeBytes: 1,
  url: 'https://www.sec.gov/doc.htm',
  indexUrl: 'https://www.sec.gov/index.htm',
  ...overrides,
});

export const makeCompany = (overrides: Partial<Company> = {}): Company => ({
  cik: '0000000001',
  name: 'Test Co',
  tickers: ['TEST'],
  ...overrides,
});

/** In-memory repository keyed by ticker. */
export const createFakeRepository = (
  byTicker: Record<string, CompanyFilings>,
): FilingsRepository => ({
  findCikByTicker: (ticker) => Promise.resolve(byTicker[ticker]?.company.cik),
  getCompanyFilings: (cik) => {
    const found = Object.values(byTicker).find((c) => c.company.cik === cik);
    return found ? Promise.resolve(found) : Promise.reject(new Error(`no fake for ${cik}`));
  },
});

