import { describe, expect, it, vi } from 'vitest';
import { withTtlCache } from './ttl-cache.js';

describe('withTtlCache', () => {
  it('reuses values within the TTL and refetches after it', async () => {
    let time = 0;
    const fn = vi.fn((key: string) => Promise.resolve(`${key}-${time}`));
    const cached = withTtlCache(fn, { ttlMs: 100, now: () => time });

    expect(await cached('a')).toBe('a-0');
    time = 50;
    expect(await cached('a')).toBe('a-0');
    time = 150;
    expect(await cached('a')).toBe('a-150');
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it('shares in-flight promises and does not cache failures', async () => {
    const fn = vi
      .fn<(key: string) => Promise<string>>()
      .mockRejectedValueOnce(new Error('boom'))
      .mockResolvedValue('ok');
    const cached = withTtlCache(fn, { ttlMs: 1000 });

    const [first, second] = await Promise.allSettled([cached('a'), cached('a')]);
    expect(first.status).toBe('rejected');
    expect(second.status).toBe('rejected');
    expect(fn).toHaveBeenCalledTimes(1);

    expect(await cached('a')).toBe('ok');
  });

  it('evicts the oldest entry beyond maxEntries', async () => {
    const fn = vi.fn((key: string) => Promise.resolve(key));
    const cached = withTtlCache(fn, { ttlMs: 1000, maxEntries: 2 });

    await cached('a');
    await cached('b');
    await cached('c'); // evicts 'a'
    await cached('a');
    expect(fn).toHaveBeenCalledTimes(4);
  });
});

