import type { Company, CompanyFilings, Filing } from './filing.domain.js';
import type { FilingsRepository } from './filings.repository.js';

export const makeFiling = (overrides: Partial<Filing> = {}): Filing => ({
  accessionNumber: `0000000000-00-${String(Math.random()).slice(2, 8)}`,
  form: '8-K',
  filingDate: '2026-01-01',
  reportDate: null,
  acceptedAt: '2026-01-01T12:00:00.000Z',
  description: null,
  primaryDocument: 'doc.htm',
  sizeBytes: 1,
  url: 'https://www.sec.gov/doc.htm',
  indexUrl: 'https://www.sec.gov/index.htm',
  ...overrides,
});

export const makeCompany = (overrides: Partial<Company> = {}): Company => ({
  cik: '0000000001',
  name: 'Test Co',
  tickers: ['TEST'],
  ...overrides,
});

/** In-memory repository keyed by ticker. */
export const createFakeRepository = (
  byTicker: Record<string, CompanyFilings>,
): FilingsRepository => ({
  findCikByTicker: (ticker) => Promise.resolve(byTicker[ticker]?.company.cik),
  getCompanyFilings: (cik) => {
    const found = Object.values(byTicker).find((c) => c.company.cik === cik);
    return found ? Promise.resolve(found) : Promise.reject(new Error(`no fake for ${cik}`));
  },
});

import { describe, expect, it } from 'vitest';
import {
  filterByForms,
  paginate,
  sortByFilingDate,
  summarizeFilings,
  twelveMonthsBefore,
} from './filings.service.js';
import { makeCompany, makeFiling } from './test-fixtures.js';

describe('filterByForms', () => {
  const filings = [makeFiling({ form: '10-K' }), makeFiling({ form: '10-Q' }), makeFiling()];

  it('returns everything when no forms given', () => {
    expect(filterByForms(filings, [])).toHaveLength(3);
  });

  it('matches case-insensitively and exactly (10-K does not match 10-K/A)', () => {
    const withAmendment = [...filings, makeFiling({ form: '10-K/A' })];
    expect(filterByForms(withAmendment, ['10-k']).map((f) => f.form)).toEqual(['10-K']);
  });
});

describe('sortByFilingDate', () => {
  const a = makeFiling({ filingDate: '2026-01-01', acceptedAt: '2026-01-01T09:00:00Z' });
  const b = makeFiling({ filingDate: '2026-01-01', acceptedAt: '2026-01-01T17:00:00Z' });
  const c = makeFiling({ filingDate: '2026-03-01' });

  it('sorts descending with acceptance time as tie-breaker', () => {
    expect(sortByFilingDate([a, c, b], 'desc')).toEqual([c, b, a]);
  });

  it('sorts ascending', () => {
    expect(sortByFilingDate([c, b, a], 'asc')).toEqual([a, b, c]);
  });
});

describe('paginate', () => {
  const items = Array.from({ length: 7 }, (_, i) => i);

  it('slices the requested page and reports totals', () => {
    expect(paginate(items, 2, 3)).toEqual({
      data: [3, 4, 5],
      pagination: { page: 2, pageSize: 3, totalItems: 7, totalPages: 3 },
    });
  });

  it('returns an empty page past the end', () => {
    expect(paginate(items, 9, 3).data).toEqual([]);
  });
});

describe('twelveMonthsBefore', () => {
  it('goes back one calendar year (UTC)', () => {
    expect(twelveMonthsBefore(new Date('2026-11-12T10:00:00Z'))).toBe('2025-11-12');
  });
});

describe('summarizeFilings', () => {
  const window = { from: '2025-11-12', to: '2026-11-12' };

  it('counts forms inside the window and finds the latest 10-K (even outside the window)', () => {
    const summary = summarizeFilings(
      'AAPL',
      {
        company: makeCompany(),
        filings: [
          makeFiling({ form: '8-K', filingDate: '2026-05-01' }),
          makeFiling({ form: '8-K', filingDate: '2026-06-01' }),
          makeFiling({ form: '10-Q', filingDate: '2026-07-01' }),
          makeFiling({ form: '10-K/A', filingDate: '2026-02-01' }),
          makeFiling({ form: '8-K', filingDate: '2025-11-11' }), // day before window
          makeFiling({ form: '10-K', filingDate: '2024-10-30' }),
          makeFiling({ form: '10-K', filingDate: '2023-10-30' }),
        ],
      },
      window,
