import { describe, expect, it } from 'vitest';
import { columnsToFilings, padCik, toTickerIndex } from './edgar.mapper.js';

describe('columnsToFilings', () => {
  it('pivots columnar data into filings with sec.gov links (unpadded CIK in URL)', () => {
    const [filing] = columnsToFilings('0000320193', {
      accessionNumber: ['0000320193-25-000079'],
      filingDate: ['2025-10-31'],
      reportDate: ['2025-09-27'],
      acceptanceDateTime: ['2025-10-31T06:01:26.000Z'],
      form: ['10-K'],
      primaryDocument: ['aapl-20250927.htm'],
      primaryDocDescription: ['10-K'],
      size: [9_000_000],
    });

    expect(filing).toEqual({
      accessionNumber: '0000320193-25-000079',
      form: '10-K',
      filingDate: '2025-10-31',
      reportDate: '2025-09-27',
      acceptedAt: '2025-10-31T06:01:26.000Z',
      description: '10-K',
      primaryDocument: 'aapl-20250927.htm',
      sizeBytes: 9_000_000,
      url: 'https://www.sec.gov/Archives/edgar/data/320193/000032019325000079/aapl-20250927.htm',
      indexUrl:
        'https://www.sec.gov/Archives/edgar/data/320193/000032019325000079/0000320193-25-000079-index.htm',
    });
  });

  it('maps EDGAR empty strings to null', () => {
    const [filing] = columnsToFilings('0000320193', {
      accessionNumber: ['0001354457-26-001062'],
      filingDate: ['2026-11-09'],
      reportDate: [''],
      acceptanceDateTime: ['2026-11-09T22:00:55.000Z'],
      form: ['25-NSE'],
      primaryDocument: ['xslF25X02/primary_doc.xml'],
      primaryDocDescription: [''],
      size: [3110],
    });

    expect(filing?.reportDate).toBeNull();
    expect(filing?.description).toBeNull();
  });
});

describe('toTickerIndex', () => {
  it('maps every ticker (including share classes) to a padded CIK', () => {
    const index = toTickerIndex({
      '0': { cik_str: 19617, ticker: 'JPM', title: 'JPMORGAN CHASE & CO' },
      '1': { cik_str: 19617, ticker: 'JPM-PC', title: 'JPMORGAN CHASE & CO' },
    });
    expect(index.get('JPM')).toBe('0000019617');
    expect(index.get('JPM-PC')).toBe('0000019617');
  });

  it('pads CIKs to 10 digits', () => {
    expect(padCik(320193)).toBe('0000320193');
  });
});

import type { Company, CompanyFilings, Filing } from './filing.domain.js';
import type { FilingsRepository } from './filings.repository.js';

export const makeFiling = (overrides: Partial<Filing> = {}): Filing => ({
  accessionNumber: `0000000000-00-${String(Math.random()).slice(2, 8)}`,
  form: '8-K',
  filingDate: '2026-01-01',
  reportDate: null,
  acceptedAt: '2026-01-01T12:00:00.000Z',
  description: null,
  primaryDocument: 'doc.htm',
  sizeBytes: 1,
  url: 'https://www.sec.gov/doc.htm',
  indexUrl: 'https://www.sec.gov/index.htm',
  ...overrides,
});

export const makeCompany = (overrides: Partial<Company> = {}): Company => ({
  cik: '0000000001',
  name: 'Test Co',
  tickers: ['TEST'],
  ...overrides,
});

/** In-memory repository keyed by ticker. */
export const createFakeRepository = (
  byTicker: Record<string, CompanyFilings>,
): FilingsRepository => ({
  findCikByTicker: (ticker) => Promise.resolve(byTicker[ticker]?.company.cik),
  getCompanyFilings: (cik) => {
    const found = Object.values(byTicker).find((c) => c.company.cik === cik);
    return found ? Promise.resolve(found) : Promise.reject(new Error(`no fake for ${cik}`));
  },
});

import { describe, expect, it } from 'vitest';
import {
  filterByForms,
  paginate,
  sortByFilingDate,
  summarizeFilings,
  twelveMonthsBefore,
} from './filings.service.js';
import { makeCompany, makeFiling } from './test-fixtures.js';

describe('filterByForms', () => {
  const filings = [makeFiling({ form: '10-K' }), makeFiling({ form: '10-Q' }), makeFiling()];

  it('returns everything when no forms given', () => {
    expect(filterByForms(filings, [])).toHaveLength(3);
  });

  it('matches case-insensitively and exactly (10-K does not match 10-K/A)', () => {
    const withAmendment = [...filings, makeFiling({ form: '10-K/A' })];
    expect(filterByForms(withAmendment, ['10-k']).map((f) => f.form)).toEqual(['10-K']);
  });
});

describe('sortByFilingDate', () => {
  const a = makeFiling({ filingDate: '2026-01-01', acceptedAt: '2026-01-01T09:00:00Z' });
  const b = makeFiling({ filingDate: '2026-01-01', acceptedAt: '2026-01-01T17:00:00Z' });
  const c = makeFiling({ filingDate: '2026-03-01' });

  it('sorts descending with acceptance time as tie-breaker', () => {
    expect(sortByFilingDate([a, c, b], 'desc')).toEqual([c, b, a]);
  });

  it('sorts ascending', () => {
    expect(sortByFilingDate([c, b, a], 'asc')).toEqual([a, b, c]);
  });
});

describe('paginate', () => {
  const items = Array.from({ length: 7 }, (_, i) => i);

  it('slices the requested page and reports totals', () => {
    expect(paginate(items, 2, 3)).toEqual({
      data: [3, 4, 5],
      pagination: { page: 2, pageSize: 3, totalItems: 7, totalPages: 3 },
    });
  });

  it('returns an empty page past the end', () => {
    expect(paginate(items, 9, 3).data).toEqual([]);
  });
});

describe('twelveMonthsBefore', () => {
  it('goes back one calendar year (UTC)', () => {
    expect(twelveMonthsBefore(new Date('2026-11-12T10:00:00Z'))).toBe('2025-11-12');
  });
});

describe('summarizeFilings', () => {
  const window = { from: '2025-11-12', to: '2026-11-12' };

  it('counts forms inside the window and finds the latest 10-K (even outside the window)', () => {
    const summary = summarizeFilings(
      'AAPL',
      {
        company: makeCompany(),
        filings: [
          makeFiling({ form: '8-K', filingDate: '2026-05-01' }),
          makeFiling({ form: '8-K', filingDate: '2026-06-01' }),
          makeFiling({ form: '10-Q', filingDate: '2026-07-01' }),
          makeFiling({ form: '10-K/A', filingDate: '2026-02-01' }),
          makeFiling({ form: '8-K', filingDate: '2025-11-11' }), // day before window
          makeFiling({ form: '10-K', filingDate: '2024-10-30' }),
          makeFiling({ form: '10-K', filingDate: '2023-10-30' }),
        ],
      },
      window,
    );

    expect(summary.formCounts).toEqual({ '8-K': 2, '10-Q': 1, '10-K/A': 1 });
    expect(summary.totalFilings).toBe(4);
    expect(summary.latest10KDate).toBe('2024-10-30');
  });

  it('returns null latest10KDate for foreign issuers that file 20-F instead', () => {
    const summary = summarizeFilings(
      'SPOT',
      { company: makeCompany(), filings: [makeFiling({ form: '20-F', filingDate: '2026-02-01' })] },
      window,
    );
    expect(summary.latest10KDate).toBeNull();
  });
});

import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createApp } from '../../app.js';
import type { FilingsPage, FilingsSummary } from './filing.domain.js';
import { createFakeRepository, makeCompany, makeFiling } from './test-fixtures.js';

const repository = createFakeRepository({
  AAPL: {
    company: makeCompany({ cik: '0000320193', name: 'Apple Inc.', tickers: ['AAPL'] }),
    filings: [
      makeFiling({ form: '10-K', filingDate: '2025-10-31' }),
      makeFiling({ form: '10-Q', filingDate: '2026-08-01' }),
      makeFiling({ form: '8-K', filingDate: '2026-09-01' }),
      makeFiling({ form: '8-K', filingDate: '2026-10-01' }),
    ],
  },
});

let server: Server;
let baseUrl: string;

beforeAll(async () => {
  const app = createApp({
    corsOrigin: '*',
    filingsRepository: repository,
    now: () => new Date('2026-11-12T00:00:00Z'),
  });
  await new Promise<void>((resolve) => {
    server = app.listen(0, resolve);
  });
  baseUrl = `http://localhost:${(server.address() as AddressInfo).port}`;
});

afterAll(() => {
  server.close();
});

const get = async <T>(path: string) => {
  const res = await fetch(`${baseUrl}${path}`);
  return { status: res.status, body: (await res.json()) as T };
};

describe('GET /companies/:ticker/filings', () => {
  it('returns a paginated page, newest first, with available forms', async () => {
    const { status, body } = await get<FilingsPage>('/companies/aapl/filings?pageSize=2');
    expect(status).toBe(200);
    expect(body.company.name).toBe('Apple Inc.');
    expect(body.data.map((f) => f.filingDate)).toEqual(['2026-10-01', '2026-09-01']);
    expect(body.pagination).toEqual({ page: 1, pageSize: 2, totalItems: 4, totalPages: 2 });
    expect(body.availableForms).toEqual(['10-K', '10-Q', '8-K']);
  });

  it('filters by form (comma-separated or repeated) and sorts ascending', async () => {
    const { body } = await get<FilingsPage>('/companies/AAPL/filings?form=10-k&form=8-K&order=asc');
    expect(body.data.map((f) => f.form)).toEqual(['10-K', '8-K', '8-K']);
  });

  it('404s for an unknown ticker', async () => {
    const { status, body } = await get('/companies/NOPE/filings');
    expect(status).toBe(404);
    expect(body).toEqual({ error: { message: 'Unknown ticker: NOPE' } });
  });

  it('400s for invalid query params', async () => {
    const { status } = await get('/companies/AAPL/filings?pageSize=1000');
    expect(status).toBe(400);
  });
});

describe('GET /filings/summary', () => {
  it('summarizes known tickers and reports unknown ones as errors', async () => {
    const { status, body } = await get<FilingsSummary>('/filings/summary?tickers=AAPL,NOPE');
    expect(status).toBe(200);
    expect(body.window).toEqual({ from: '2025-11-12', to: '2026-11-12' });
    expect(body.data).toHaveLength(1);
    expect(body.data[0]).toMatchObject({
      ticker: 'AAPL',
      formCounts: { '10-Q': 1, '8-K': 2 },
      latest10KDate: '2025-10-31',
    });
    expect(body.errors).toEqual([{ ticker: 'NOPE', status: 404, message: 'Unknown ticker: NOPE' }]);
  });

  it('400s without tickers', async () => {
    const { status } = await get('/filings/summary');
    expect(status).toBe(400);
  });
});

describe('error handling', () => {
  it('returns 400 (not 500) for a malformed JSON body', async () => {
    const res = await fetch(`${baseUrl}/health`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: '{bad',
    });
    expect(res.status).toBe(400);
  });
});

import { describe, expect, it, vi } from 'vitest';
import { withTtlCache } from './ttl-cache.js';

describe('withTtlCache', () => {
  it('reuses values within the TTL and refetches after it', async () => {
    let time = 0;
    const fn = vi.fn((key: string) => Promise.resolve(`${key}-${time}`));
    const cached = withTtlCache(fn, { ttlMs: 100, now: () => time });

    expect(await cached('a')).toBe('a-0');
    time = 50;
    expect(await cached('a')).toBe('a-0');
    time = 150;
    expect(await cached('a')).toBe('a-150');
    expect(fn).toHaveBeenCalledTimes(2);
  });

  it('shares in-flight promises and does not cache failures', async () => {
    const fn = vi
      .fn<(key: string) => Promise<string>>()
      .mockRejectedValueOnce(new Error('boom'))
      .mockResolvedValue('ok');
    const cached = withTtlCache(fn, { ttlMs: 1000 });

    const [first, second] = await Promise.allSettled([cached('a'), cached('a')]);
    expect(first.status).toBe('rejected');
    expect(second.status).toBe('rejected');
    expect(fn).toHaveBeenCalledTimes(1);

    expect(await cached('a')).toBe('ok');
  });

  it('evicts the oldest entry beyond maxEntries', async () => {
    const fn = vi.fn((key: string) => Promise.resolve(key));
    const cached = withTtlCache(fn, { ttlMs: 1000, maxEntries: 2 });

    await cached('a');
    await cached('b');
    await cached('c'); // evicts 'a'
    await cached('a');
    expect(fn).toHaveBeenCalledTimes(4);
  });
});

