import cors from 'cors';
import express, { type Express } from 'express';
import { createFilingsController } from './domains/filings/filings.controller.js';
import type { FilingsRepository } from './domains/filings/filings.repository.js';
import { createFilingsRouter } from './domains/filings/filings.routes.js';
import { createFilingsService } from './domains/filings/filings.service.js';
import { errorHandler, notFoundHandler } from './middleware/error-handler.js';

interface AppDeps {
  corsOrigin: string;
  /** Injected so tests can pass a fake instead of hitting EDGAR. */
  filingsRepository: FilingsRepository;
  now?: () => Date;
}

/** Composition root: repository → service → controller → router. */
export function createApp({ corsOrigin, filingsRepository, now }: AppDeps): Express {
  const app = express();
  app.use(cors({ origin: corsOrigin }));
  app.use(express.json());

  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });

  const filingsService = createFilingsService({
    repository: filingsRepository,
    ...(now && { now }),
  });
  app.use(createFilingsRouter(createFilingsController(filingsService)));

  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

