const SUBMISSIONS_BASE_URL = 'https://data.sec.gov/submissions';

type CompanyTickers = Record<string, { cik_str: number; ticker: string; title: string }>;

export const createFilingsRepository = (userAgent: string) => {
  const fetchJson = async (url: string): Promise<unknown> => {
    const res = await fetch(url, { headers: { 'User-Agent': userAgent } });
    if (!res.ok) throw new Error(`EDGAR responded ${res.status} for ${url}`);
    return res.json();
  };

  return {
    getCompanyTickers: async () => (await fetchJson(TICKERS_URL)) as CompanyTickers,
    /** `cik` must be zero-padded to 10 digits. */
    getSubmissions: (cik: string) => fetchJson(`${SUBMISSIONS_BASE_URL}/CIK${cik}.json`),
  };
};

export type FilingsRepository = ReturnType<typeof createFilingsRepository>;

import { notFound } from '../../utils/http-error.js';
import type { FilingsRepository } from './filings.repository.js';

export const createFilingsService = (repository: FilingsRepository) => ({
  /** Resolves ticker → CIK, then returns EDGAR's raw submissions response. */
  getFilings: async (ticker: string) => {
    const tickers = await repository.getCompanyTickers();
    const company = Object.values(tickers).find((c) => c.ticker === ticker.toUpperCase());
    if (!company) throw notFound(`Unknown ticker: ${ticker}`);

    const cik = String(company.cik_str).padStart(10, '0');
    return repository.getSubmissions(cik);
  },
});

export type FilingsService = ReturnType<typeof createFilingsService>;

import { Router } from 'express';
import type { FilingsService } from './filings.service.js';

export const createFilingsRouter = (service: FilingsService) =>
  Router().get('/companies/:ticker/filings', async (req, res) => {
    res.json(await service.getFilings(req.params.ticker));
  });

