import { orderBy } from 'es-toolkit';
import { notFound } from '../../utils/http-error.js';
import type { FilingColumns, FilingsRepository } from './filings.repository.js';

/** One filing, with EDGAR's own field names (form, filingDate, accessionNumber, …). */
export type Filing = Record<string, string | number | undefined>;

export interface FilingsQuery {
  /** Form types to keep, e.g. ['10-K', '8-K']. Empty = all. */
  forms: string[];
  sort: 'asc' | 'desc';
}

/** Turns EDGAR's columns into one object per filing. */
const toRows = (columns: FilingColumns): Filing[] =>
  (columns.accessionNumber ?? []).map((_, i) =>
    Object.fromEntries(Object.entries(columns).map(([key, values]) => [key, values[i]])),
  );

export const createFilingsService = (repository: FilingsRepository) => ({
  getFilings: async (ticker: string, { forms, sort }: FilingsQuery): Promise<Filing[]> => {
    const tickers = await repository.getCompanyTickers();
    const company = Object.values(tickers).find((c) => c.ticker === ticker.toUpperCase());
    if (!company) throw notFound(`Unknown ticker: ${ticker}`);

    const cik = String(company.cik_str).padStart(10, '0');
    const submissions = await repository.getSubmissions(cik);

    const filings = toRows(submissions.filings.recent);
    const filtered =
      forms.length === 0 ? filings : filings.filter((f) => forms.includes(String(f.form)));
    return orderBy(filtered, ['filingDate'], [sort]);
  },
});

export type FilingsService = ReturnType<typeof createFilingsService>;

