import { Router } from 'express';
import { z } from 'zod';
import type { FilingsService } from './filings.service.js';

const FilingsQuerySchema = z.object({
  /** Comma-separated, e.g. `?form=10-K,8-K`. Case-insensitive. */
  form: z
    .string()
    .optional()
    .transform((v) =>
      (v ?? '')
        .split(',')
        .map((f) => f.trim().toUpperCase())
        .filter(Boolean),
    ),
  sort: z.enum(['asc', 'desc']).default('desc'),
});

export const createFilingsRouter = (service: FilingsService) =>
  Router().get('/companies/:ticker/filings', async (req, res) => {
    const { form, sort } = FilingsQuerySchema.parse(req.query);
    const filings = await service.getFilings(req.params.ticker, { forms: form, sort });
    res.json({ data: filings });
  });

