import { Button, Stack, TextField, Typography } from '@mui/material';
import { createFileRoute, useNavigate } from '@tanstack/react-router';
import { useState } from 'react';

export const Route = createFileRoute('/')({
  component: HomePage,
});

function HomePage() {
  const navigate = useNavigate();
  const [ticker, setTicker] = useState('AAPL');

  return (
    <Stack spacing={2} className="max-w-sm">
      <Typography variant="h4">Look up a company</Typography>
      <form
        className="flex gap-2"
        onSubmit={(e) => {
          e.preventDefault();
          void navigate({ to: '/companies/$ticker', params: { ticker: ticker.trim() } });
        }}
      >
        <TextField
          label="Ticker"
          size="small"
          value={ticker}
          onChange={(e) => {
            setTicker(e.target.value.toUpperCase());
          }}
        />
        <Button type="submit" variant="contained" disabled={!ticker.trim()}>
          Go
        </Button>
      </form>
    </Stack>
  );
}

