const SUBMISSIONS_BASE_URL = 'https://data.sec.gov/submissions';

/** The SEC updates the ticker file roughly daily. */
const TICKERS_TTL_MS = 24 * 60 * 60 * 1000;

export const createFilingsRepository = (userAgent: string) => {
  const fetchJson = async (url: string): Promise<unknown> => {
    const res = await fetch(url, { headers: { 'User-Agent': userAgent } });
    if (!res.ok) throw new Error(`EDGAR responded ${res.status} for ${url}`);
    return res.json();
  };

  let tickersCache: { promise: Promise<CompanyTickers>; expiresAt: number } | undefined;

  /**
   * Caches the promise rather than the result, and checks + stores it synchronously (no await in
   * between). Concurrent callers therefore share one in-flight request instead of each
   * downloading the ~800 KB file.
   */
  function getCompanyTickers(): Promise<CompanyTickers> {
    if (tickersCache && tickersCache.expiresAt > Date.now()) return tickersCache.promise;

    const promise = fetchJson(TICKERS_URL).then((data) => companyTickersSchema.parse(data));
    const entry = { promise, expiresAt: Date.now() + TICKERS_TTL_MS };
    tickersCache = entry;

    // Don't cache failures: the next call retries. Only clear our own entry, in case a newer
    // one replaced it meanwhile.
    void promise.catch(() => {
      if (tickersCache === entry) tickersCache = undefined;
    });

    return promise;
  }

