    select: (summary) => summary.data.map(toSummaryRow),
    enabled: tickers.length > 0,
    staleTime: 5 * 60 * 1000,
    placeholderData: keepPreviousData,
  });

export function useSummary(tickers: string[]) {
  return useQuery(summaryQueryOptions(tickers));
}

