    39	export const createFilingsService = (repository: FilingsRepository) => {
    40	  const getCompanyFilings = async (ticker: string): Promise<Filing[]> => {
    41	    const tickers = await repository.getCompanyTickers();
    42	    const matchedCompany = Object.values(tickers).find(
    43	      (company) => company.ticker === ticker.toUpperCase(),
    44	    );
    45	    if (!matchedCompany) throw notFound(`Unknown ticker: ${ticker}`);
    46	
    47	    const submissions = await repository.getSubmissions(matchedCompany.cik);
    48	    return submissionsToRecentFilings(submissions);
    49	  };
    50	
    51	  const getFilings = async (
    52	    ticker: string,
    53	    { form, sort, page, pageSize }: FilingsQuery,
    54	  ): Promise<FilingsPage> => {
    55	    const filings = await getCompanyFilings(ticker);
    56	    const filtered = form.length === 0 ? filings : filings.filter((f) => form.includes(f.form));
    57	    const sorted = orderBy(filtered, ['filingDate'], [sort]);
    58	
    59	    // Paginate last, so totals reflect the active filter. A page past the end is just empty.
    60	    const start = (page - 1) * pageSize;
    61	    return {
    62	      data: sorted.slice(start, start + pageSize),
    63	      pagination: {
    64	        page,
    65	        pageSize,
    66	        totalItems: sorted.length,
    67	        totalPages: Math.ceil(sorted.length / pageSize),
    68	      },
    69	    };
    70	  };
    71	
    72	  const getSummary = async ({ tickers }: SummaryQuery): Promise<Summary> => {
    73	    const since = oneYearAgo();
    74	
    75	    // EDGAR's `filings.recent` always covers at least the last year, so no extra requests.
    76	    const data = await Promise.all(
    77	      tickers.map(async (ticker): Promise<CompanySummary> => {
    78	        const filings = orderBy(await getCompanyFilings(ticker), ['filingDate'], ['desc']);
    79	        const lastYear = filings.filter((f) => f.filingDate >= since);
    80	        return {
    81	          ticker,
    82	          formCounts: countBy(lastYear, (f) => f.form),
    83	          latestAnnualReport: findLatestAnnualReport(filings),
    84	        };
    85	      }),
    86	    );
    87	
    88	    return { data };
    89	  };
    90	
    91	  return { getFilings, getSummary };
    92	};
