    12	export const createFilingsRepository = (userAgent: string) => {
    13	  const fetchJson = async (url: string): Promise<unknown> => {
    14	    const res = await fetch(url, { headers: { 'User-Agent': userAgent } });
    15	    if (!res.ok) throw new Error(`EDGAR responded ${res.status} for ${url}`);
    16	    return res.json();
    17	  };
