    19	  // Fetched once per server start; the promise is cached, so concurrent calls share one request.
    20	  // TODO: Expire daily and don't cache a failed fetch. This is used for now for simplicity
    21	  const getCompanyTickers = memoize((): Promise<CompanyTickers> =>
    22	    fetchJson(TICKERS_URL).then((data) => companyTickersSchema.parse(data)),
    23	  );
    24	
    25	  /**
    26	   * `cik` must be zero-padded to 10 digits. Cached per CIK (memoize keys on the first argument),
    27	   * so paging/filtering doesn't refetch from EDGAR.
    28	   * TODO: Same as tickers: expire (new filings appear over the day) and don't cache failures.
    29	   */
    30	  const getSubmissions = memoize((cik: string): Promise<Submissions> =>
    31	    fetchJson(`${SUBMISSIONS_BASE_URL}/CIK${cik}.json`).then((data) =>
    32	      submissionsSchema.parse(data),
    33	    ),
    34	  );
    35	
    36	  return {
    37	    getCompanyTickers,
    38	    getSubmissions,
    39	  };
    40	};
