    16	/** Same day one year ago, as YYYY-MM-DD (comparable with `filingDate` as a string). */
    17	const oneYearAgo = (): string => {
    18	  const date = new Date();
    19	  date.setUTCFullYear(date.getUTCFullYear() - 1);
    20	  return date.toISOString().slice(0, 10);
    21	};
    22	
    23	/** `filing.form` is a plain string, so compare as strings rather than against the enum. */
    24	const isForm = (filing: Filing, form: string): boolean => filing.form === form;
    25	
    26	/** Latest 10-K, else latest 20-F/40-F (foreign companies). Expects filings newest first. */
    27	const findLatestAnnualReport = (filings: Filing[]): AnnualReport | null => {
    28	  const tenK = filings.find((f) => isForm(f, FormType.K10));
    29	  if (tenK) return { form: FormType.K10, filingDate: tenK.filingDate };
    30	
    31	  const foreign = filings.find((f) => isForm(f, FormType.F20) || isForm(f, FormType.F40));
    32	  if (!foreign) return null;
    33	  return {
    34	    form: isForm(foreign, FormType.F20) ? FormType.F20 : FormType.F40,
    35	    filingDate: foreign.filingDate,
    36	  };
    37	};
