     1	/**
     2	 * Errors that carry an HTTP status. Follows the `http-errors` convention (`status` + `expose`),
     3	 * which Express middleware like `express.json()` also uses, e.g. 400 for a malformed JSON body.
     4	 */
     5	export type HttpError = Error & {
     6	  status: number;
     7	  /** Whether `message` is safe to send to the client. */
     8	  expose: boolean;
     9	};
    10	
    11	export const httpError = (status: number, message: string): HttpError =>
    12	  Object.assign(new Error(message), { name: 'HttpError', status, expose: status < 500 });
    13	
    14	export const notFound = (message: string): HttpError => httpError(404, message);
    15	
    16	/** Upstream (EDGAR) failed or returned something we couldn't understand. */
    17	export const badGateway = (message: string): HttpError =>
    18	  // Our own 502 messages are safe to show; they don't leak internals.
    19	  Object.assign(httpError(502, message), { expose: true });
    20	
    21	export const isHttpError = (err: unknown): err is HttpError =>
    22	  err instanceof Error &&
    23	  'status' in err &&
    24	  typeof err.status === 'number' &&
    25	  'expose' in err &&
    26	  typeof err.expose === 'boolean';
