     5	export class ApiError extends Error {
     6	  constructor(
     7	    public readonly status: number,
     8	    message: string,
     9	  ) {
    10	    super(message);
    11	    this.name = 'ApiError';
    12	  }
    13	}
    14	
    15	interface ApiErrorBody {
    16	  error?: { message?: string };
    17	}
    18	
    19	/**
    20	 * Thin fetch wrapper: prefixes the API base URL, throws ApiError on non-2xx, and parses the
    21	 * JSON body with `schema` so the result is validated rather than asserted.
    22	 */
    23	export async function apiFetch<T extends z.ZodType>(
    24	  path: string,
    25	  schema: T,
    26	  init?: RequestInit,
    27	): Promise<z.infer<T>> {
    28	  const res = await fetch(`${API_BASE_URL}${path}`, init);
    29	  if (!res.ok) {
    30	    const body = (await res.json().catch(() => ({}))) as ApiErrorBody;
    31	    throw new ApiError(res.status, body.error?.message ?? `Request failed (${res.status})`);
    32	  }
    33	  return schema.parse(await res.json());
    34	}
